+static void
+ssh_increment_packet_number(packet_info *pinfo, struct ssh_flow_data *global_data,
+        gboolean is_response)
+{
+    if (!PINFO_FD_VISITED(pinfo)) {
+        ssh_packet_info_t *packet = wmem_new0(wmem_file_scope(), ssh_packet_info_t);
+        p_add_proto_data(wmem_file_scope(), pinfo, proto_ssh, 0, packet);
+        packet->sequence_number =
+            global_data->peer_data[!is_response].sequence_number;
+        global_data->peer_data[!is_response].sequence_number++;
+        packet->from_server = is_response;
+    }
+}
+
+static guint
+ssh_decrypt_packet(tvbuff_t *tvb, packet_info *pinfo,
+        struct ssh_peer_data *peer_data, int offset, proto_tree *tree)
+{
+    ssh_packet_info_t *packet = (ssh_packet_info_t *)p_get_proto_data(
+            wmem_file_scope(), pinfo, proto_ssh, 0);
+
+    if (!PINFO_FD_VISITED(pinfo)) {
+        DISSECTOR_ASSERT(packet);
+        packet->offset = offset;
+    } else {
+        offset = packet->offset;
+    }
+
+    guint packet_length, seqnr;
+    gchar *mac;
+    size_t mac_len;
+    gchar *ctext = (gchar *)tvb_memdup(wmem_packet_scope(), tvb, offset, 4);
+
+    seqnr = packet->sequence_number;
+
+    if (GCRY_CIPHER_CHACHA20 == peer_data->cipher_id) {
+        if (!ssh_decrypt_chacha20(peer_data->cipher_length, seqnr, 0, ctext, 4)) {
+            g_debug("ERROR: could not decrypt packet len");
+            return 0;
+        }
+
+        packet_length = pntoh32(ctext);
+
+        gchar *ctext2 = (gchar *)tvb_get_ptr(tvb, offset+4,
+                packet_length);
+
+        if (!ssh_decrypt_chacha20(peer_data->cipher, seqnr, 1, ctext2,
+                    packet_length)) {
+            g_debug("ERROR: could not decrypt packet payload");
+            return 0;
+        }
+
+        mac_len = 16;
+        mac = (gchar *)tvb_get_ptr(tvb, offset + 4 + packet_length, mac_len);
+        gchar poly_key[32], iv[16];
+
+        memset(poly_key, 0, 32);
+        memset(iv, 0, 8);
+        phton64(iv+8, (guint64)seqnr);
+        gcry_cipher_setiv(peer_data->cipher, iv, mac_len);
+        gcry_cipher_encrypt(peer_data->cipher, poly_key, 32, poly_key, 32);
+
+        gcry_mac_hd_t mac_hd;
+        gcry_mac_open(&mac_hd, GCRY_MAC_POLY1305, 0, NULL);
+        gcry_mac_setkey(mac_hd, poly_key, 32);
+        gcry_mac_write(mac_hd, ctext, 4);
+        gcry_mac_write(mac_hd, ctext2, packet_length);
+
+        if (gcry_mac_verify(mac_hd, mac, mac_len)) {
+            g_debug("ssh: MAC does not match");
+            gcry_mac_close(mac_hd);
+            return 0;
+        }
+
+        gcry_mac_close(mac_hd);
+    } else {
+        return 0;
+    }
+
+    ssh_dissect_decrypted_packet(plain, plain_length, mac, mac_len,
+            tree, tvb, pinfo);
+    offset += packet_length + peer_data->mac_length + 4;
+    return offset;
+}
+
+static gboolean
+ssh_decrypt_chacha20(gcry_cipher_hd_t hd, guint32 seqnr, guint32 counter,
+        guchar *ctext, guint ctext_len)
+{
+    guchar seq[8];
+    guchar iv[16];
+
+    phton64(seq, (guint64)seqnr);
+
+    // chacha20 uses a different cipher handle for the packet payload & length
+    // the payload uses a block counter
+    if (counter) {
+        guchar ctr[8] = {1,0,0,0,0,0,0,0};
+        memcpy(iv, ctr, 8);
+        memcpy(iv+8, seq, 8);
+    }
+
+    return ((!counter && gcry_cipher_setiv(hd, seq, 8) == 0) ||
+            (counter && gcry_cipher_setiv(hd, iv, 16) == 0)) &&
+            gcry_cipher_decrypt(hd, ctext, ctext_len, NULL, 0) == 0;
+}
+
+static void
+ssh_close_ciphers(struct ssh_peer_data *peer_data)
+{
+    if (peer_data->cipher) {
+        gcry_cipher_close(peer_data->cipher);
+        peer_data->cipher = NULL;
+    }
+
+    if (peer_data->cipher_length) {
+        gcry_cipher_close(peer_data->cipher_length);
+        peer_data->cipher_length = NULL;
+    }
+}
+
+static gboolean
+ssh_flow_data_destroy_cb(wmem_allocator_t *allocator _U_,
+        wmem_cb_event_t event _U_, void *user_data)
+{
+    struct ssh_flow_data *global_data = (struct ssh_flow_data *)user_data;
+    ssh_close_ciphers(&global_data->peer_data[0]);
+    ssh_close_ciphers(&global_data->peer_data[1]);
+    return FALSE;
+}
+
+static void
+ssh_dissect_decrypted_packet(gchar *plaintext, guint plaintext_len,
+        gchar *mac, guint mac_len, proto_tree *tree, tvbuff_t *tvb,
+        packet_info *pinfo)
+{
+    guint padding_len = plaintext[4];
+    guint packet_len = pntoh32(plaintext) - padding_len - 1;
+    tvbuff_t *packet_tvb = tvb_new_child_real_data(tvb, plaintext, plaintext_len,
+            plaintext_len);
+    tvbuff_t *mac_tvb = tvb_new_child_real_data(tvb, mac, mac_len, mac_len);
+    add_new_data_source(pinfo, packet_tvb, "Decrypted Packet");
+    add_new_data_source(pinfo, mac_tvb, "Packet Mac");
+    proto_tree_add_item(tree, hf_ssh_packet_length, packet_tvb, 0, 4,
+            ENC_BIG_ENDIAN);
+    proto_tree_add_item(tree, hf_ssh_padding_length, packet_tvb, 4, 1,
+            ENC_BIG_ENDIAN);
+    proto_tree_add_item(tree, hf_ssh_payload, packet_tvb, 5, packet_len,
+            ENC_BIG_ENDIAN);
+    proto_tree_add_item(tree, hf_ssh_padding_string, packet_tvb, packet_len + 5,
+            padding_len, ENC_BIG_ENDIAN);
+    proto_tree_add_item(tree, hf_ssh_mac_string, mac_tvb, 0, mac_len,
+            ENC_BIG_ENDIAN);
+}
 #endif /* SSH_DECRYPTION_SUPPORTED */

